import { describe, expect, it } from "vitest";
import {
  getEffectivePlan,
  hasUnresolvedBillingPeriod,
  type EntitlementUser,
} from "@/lib/entitlements";
import { resolveUsagePeriods } from "@/lib/usage-periods";
const start = new Date("2026-12-01T00:00:00Z"),
  end = new Date("2027-01-01T00:00:00Z"),
  grace = new Date("2027-01-04T00:00:00Z");
const user: EntitlementUser = {
  id: "owner",
  plan: "PAID",
  subscriptionStatus: "ACTIVE",
  dodoSubscriptionId: "sub",
  currentPeriodStart: start,
  currentPeriodEnd: end,
  gracePeriodEnd: null,
  planOverride: null,
  planOverrideStartsAt: null,
  planOverrideExpiresAt: null,
  grandfatheredUntil: null,
  isSuspended: false,
  deletionRequestedAt: null,
  gmailAuthorized: true,
};
describe("subscription access boundaries", () => {
  it.each([-1, 0, 1])(
    "scheduled cancellation resolves at deadline %+i ms",
    (offset) => {
      const at = new Date(+end + offset),
        cancelled = { ...user, cancelAtPeriodEnd: true };
      expect(getEffectivePlan(cancelled, at)).toBe(
        offset < 0 ? "PAID" : "FREE",
      );
      expect(hasUnresolvedBillingPeriod(cancelled, at)).toBe(false);
      const periods = resolveUsagePeriods(cancelled, at);
      expect(
        periods.monthly.key.startsWith(offset < 0 ? "provider:" : "month:"),
      ).toBe(true);
      expect(periods.daily.startsAt.toISOString()).toBe(
        offset < 0 ? "2026-12-31T00:00:00.000Z" : end.toISOString(),
      );
    },
  );
  it.each([-1, 0, 1])("signed grace resolves at deadline %+i ms", (offset) => {
    const at = new Date(+grace + offset),
      due = {
        ...user,
        subscriptionStatus: "PAST_DUE" as const,
        gracePeriodEnd: grace,
      };
    expect(getEffectivePlan(due, at)).toBe(offset < 0 ? "PAID" : "FREE");
    expect(hasUnresolvedBillingPeriod(due, at)).toBe(false);
    expect(resolveUsagePeriods(due, at).monthly.limit).toBe(
      offset < 0 ? 300 : 15,
    );
  });
  it("never invents ordinary renewal or unsigned grace credit", () => {
    for (const candidate of [
      user,
      { ...user, subscriptionStatus: "PAST_DUE" as const },
    ]) {
      expect(hasUnresolvedBillingPeriod(candidate, end)).toBe(true);
      expect(() => resolveUsagePeriods(candidate, end)).toThrow("verified");
    }
  });
  it("extends one allowance on entering grace", () => {
    const before = resolveUsagePeriods(user, new Date(+end - 1));
    const due = resolveUsagePeriods(
      { ...user, subscriptionStatus: "PAST_DUE", gracePeriodEnd: grace },
      end,
    );
    expect(due.monthly.key).toBe(before.monthly.key);
    expect(due.monthly.endsAt).toEqual(end);
    expect(due.monthly.operationalEndsAt).toEqual(grace);
  });
  it("preserves overrides and transition benefits at the provider deadline", () => {
    const cancelled = { ...user, cancelAtPeriodEnd: true };
    expect(
      getEffectivePlan({ ...cancelled, grandfatheredUntil: grace }, end),
    ).toBe("PAID");
    expect(
      getEffectivePlan(
        {
          ...cancelled,
          planOverride: "PAID",
          planOverrideStartsAt: start,
          planOverrideExpiresAt: grace,
        },
        end,
      ),
    ).toBe("PAID");
    expect(
      getEffectivePlan({ ...cancelled, grandfatheredUntil: grace }, grace),
    ).toBe("FREE");
  });
});
